/* @autogenerated */
package net.civeira.phylax.feature.observe.anomaly;

import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import com.fasterxml.jackson.databind.ObjectMapper;

import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.observe.issue.IssueFingerprint;
import net.civeira.phylax.feature.observe.store.Levels;
import net.civeira.phylax.feature.observe.store.ObsLog;

/**
 * Templates of the WARN, ERROR and FATAL logs of each source (the message with its numbers, UUIDs
 * and hex values as {@code ?}): a template that was never seen before is a new pattern, often the
 * first sign of a problem. The known templates are kept in {@code patterns.jsonl}, so a restart
 * does not make every template new again. At most {@code MAX} templates are kept in memory.
 */
@Slf4j
public class LogPatterns {

  private static final int MAX = 20_000;
  private static final int MAX_TEMPLATE = 200;

  /** A template of a source and level, with its first appearance and an example. */
  public record Pattern(String src, String level, String template, long firstSeen, long count,
      String example) {}

  private record Known(String src, String level, String template, long firstSeen) {}

  private final Path file;
  private final ObjectMapper mapper = new ObjectMapper();
  private final Map<String, long[]> counts = new ConcurrentHashMap<>();
  private final Map<String, Pattern> patterns = new ConcurrentHashMap<>();

  public LogPatterns(final Path root) {
    this.file = root.resolve("patterns.jsonl");
  }

  /** Loads the known templates (they are not new). */
  public void load() {
    if (!Files.isRegularFile(file)) {
      return;
    }
    try {
      for (String line : Files.readAllLines(file, StandardCharsets.UTF_8)) {
        if (line.isBlank() || patterns.size() >= MAX) {
          continue;
        }
        Known known = mapper.readValue(line, Known.class);
        patterns.put(key(known.src(), known.level(), known.template()),
            new Pattern(known.src(), known.level(), known.template(), known.firstSeen(), 0, null));
      }
    } catch (IOException | RuntimeException ex) {
      log.warn("Unable to load the log patterns: {}", ex.getMessage());
    }
  }

  /** The WARN or higher logs of a batch (called by the writer). */
  public void observe(final List<ObsLog> logs) {
    List<Known> created = new ArrayList<>();
    for (ObsLog log : logs) {
      if (!Levels.atLeast(log.level(), "WARN") || null == log.msg() || log.msg().isBlank()) {
        continue;
      }
      String template = template(log.msg());
      String key = key(log.src(), log.level(), template);
      Pattern known = patterns.get(key);
      if (null == known) {
        if (patterns.size() >= MAX) {
          continue;
        }
        Pattern pattern = new Pattern(log.src(), log.level(), template, log.ts(), 0,
            log.msg().length() > 500 ? log.msg().substring(0, 500) : log.msg());
        if (null == patterns.putIfAbsent(key, pattern)) {
          created.add(new Known(log.src(), log.level(), template, log.ts()));
        }
      }
      counts.computeIfAbsent(key, k -> new long[1])[0]++;
    }
    if (!created.isEmpty()) {
      append(created);
    }
  }

  /** The templates first seen after {@code since}, newest first. */
  public List<Pattern> since(final long since) {
    return patterns.entrySet().stream().filter(entry -> entry.getValue().firstSeen() >= since)
        .map(entry -> {
          Pattern pattern = entry.getValue();
          long[] count = counts.get(entry.getKey());
          return new Pattern(pattern.src(), pattern.level(), pattern.template(),
              pattern.firstSeen(), null == count ? 0 : count[0], pattern.example());
        }).sorted(Comparator.comparingLong(Pattern::firstSeen).reversed()).limit(200).toList();
  }

  static String template(final String message) {
    String template = IssueFingerprint.normalize(message);
    return template.length() > MAX_TEMPLATE ? template.substring(0, MAX_TEMPLATE) : template;
  }

  private static String key(final String src, final String level, final String template) {
    return src + "\n" + level + "\n" + template;
  }

  private synchronized void append(final List<Known> created) {
    try {
      Files.createDirectories(file.getParent());
      try (BufferedWriter writer = Files.newBufferedWriter(file, StandardCharsets.UTF_8,
          StandardOpenOption.CREATE, StandardOpenOption.APPEND)) {
        for (Known known : created) {
          writer.write(mapper.writeValueAsString(known));
          writer.newLine();
        }
      }
    } catch (IOException ex) {
      log.warn("Unable to save the log patterns: {}", ex.getMessage());
    }
  }
}
